Use `pg` (node-postgres) with `Pool`:

```javascript
import { Pool } from 'pg';

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  // Pool sizing
  max: 20,                    // max connections
  min: 2,                     // keep alive minimum
  idleTimeoutMillis: 30000,   // kill idle connection after 30s
  connectionTimeoutMillis: 5000, // fail fast if can't connect in 5s
  // Query timeout (postgres-level)
  statement_timeout: 10000,
  query_timeout: 10000,
});

// Catch pool-level errors (network drops, server restart)
pool.on('error', (err, client) => {
  console.error('Idle client error:', err);
});

// Wrapper with automatic release
export async function query(text, params) {
  const start = Date.now();
  try {
    const res = await pool.query(text, params);
    return res;
  } catch (err) {
    // Re-throw with query context attached
    err.query = text;
    throw err;
  } finally {
    // Log slow queries
    const duration = Date.now() - start;
    if (duration > 1000) console.warn('Slow query:', { text, duration });
  }
}

// For transactions — must hold same client
export async function withTransaction(fn) {
  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    const result = await fn(client);
    await client.query('COMMIT');
    return result;
  } catch (err) {
    await client.query('ROLLBACK');
    throw err;
  } finally {
    client.release();
  }
}

// Graceful shutdown
process.on('SIGTERM', () => pool.end());
```

Key points:

- `max: 20` — tune to `(num_cores * 2) + effective_spindle_count`, or just start at 10
- `connectionTimeoutMillis` — without this, `pool.query()` hangs forever if pool exhausted
- `statement_timeout` — postgres kills runaway queries server-side (not just client-side)
- `pool.on('error')` mandatory — unhandled idle client errors crash Node process
- `client.release()` in `finally` — leak-proof even on throw

For production, add `pgBouncer` in front if you exceed ~100 app instances.
